// Each gradient/clip pair paints only its own part of the artwork.
const ZONES: Record<string, string> = {
  TL: '<rect x="0" y="0" width="1024" height="400"/>',
  BL: '<rect x="0" y="1200" width="745" height="336"/>',
  BR: '<rect x="745" y="1200" width="279" height="336"/>',
  Top: '<rect x="0" y="0" width="1024" height="400"/>',
  Bottom: '<rect x="0" y="1200" width="1024" height="336"/>',
};

const gradientMarkup = (g: GradientDef): string =>
  `<linearGradient id="${g.id}" gradientUnits="userSpaceOnUse" x1="${g.x1}" y1="${g.y1}" x2="${g.x2}" y2="${g.y2}">` +
  g.stops.map(([o, c]) => `<stop offset="${o}" stop-color="${c}"/>`).join('') +
  `</linearGradient>`;

const clipMarkup = (): string =>
  Object.entries(ZONES)
    .map(([k, shape]) => `<clipPath id="clip${k}">${shape}</clipPath>`)
    .join('');

/** Returns the complete background as an SVG string. */
export function getBackgroundSvg(options?: {
  primaryColor?: string;
  goldColor?: string;
}): string {
  const isDefaultPrimary =
    !options?.primaryColor || options.primaryColor.toLowerCase() === '#0e2b5d';
  const isDefaultGold =
    !options?.goldColor || options.goldColor.toLowerCase() === '#cf9d38';

  let activeGradients = GRADIENTS;

  if (!isDefaultPrimary || !isDefaultGold) {
    const primaryColor = sanitizeHexColor(options?.primaryColor, '#0e2b5d');
    const goldColor = sanitizeHexColor(options?.goldColor, '#cf9d38');

    const metallicStops = generateMetallicStops(goldColor).map(
      (s) => [s.offset.replace('%', ''), s.color] as [string, string]
    );

    activeGradients = GRADIENTS.map((g) => {
      if (g.id.startsWith('gold') || g.id.startsWith('core')) {
        return {
          ...g,
          stops: metallicStops.map(([off, col]) => [
            (Number(off) / 100).toFixed(3),
            g.id.startsWith('core') ? adjustBrightness(col, 0.08) : col,
          ] as [string, string]),
        };
      }
      if (g.id === 'navyTL' || g.id === 'navyBottom') {
        return {
          ...g,
          stops: [
            ['0.000', adjustBrightness(primaryColor, -0.45)],
            ['0.250', adjustBrightness(primaryColor, -0.2)],
            ['0.500', primaryColor],
            ['0.750', adjustBrightness(primaryColor, -0.15)],
            ['1.000', adjustBrightness(primaryColor, -0.4)],
          ],
        };
      }
      return g;
    });
  }

  const defs =
    activeGradients.map(gradientMarkup).join('') +
    clipMarkup() +
    `<filter id="soft" x="-2%" y="-2%" width="104%" height="104%"><feGaussianBlur stdDeviation="0.6"/></filter>`;

  const watermark = WATERMARK_LAYERS.map(
    (l) => `<path d="${l.d}" fill="${l.fill}" fill-rule="evenodd"/>`
  ).join('');

  const paint = (d: string, fill: string, clip: string, extra = ''): string =>
    `<path d="${d}" fill="url(#${fill})" clip-path="url(#clip${clip})" fill-rule="evenodd"${extra}/>`;

  const goldZones: [string, string][] = [
    ['TL', 'TL'],
    ['BL', 'BL'],
    ['BR', 'BR'],
  ];

  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${BACKGROUND_WIDTH}" height="${BACKGROUND_HEIGHT}" viewBox="0 0 ${BACKGROUND_WIDTH} ${BACKGROUND_HEIGHT}" preserveAspectRatio="xMidYMid slice">` +
    `<defs>${defs}</defs>` +
    `<rect width="${BACKGROUND_WIDTH}" height="${BACKGROUND_HEIGHT}" fill="${BACKGROUND_COLOR}"/>` +
    `<g transform="translate(${WATERMARK_ORIGIN.x} ${WATERMARK_ORIGIN.y})">${watermark}</g>` +
    paint(NAVY_SHAPE, 'navyBottom', 'Bottom') +
    paint(NAVY_SHAPE, 'navyTL', 'Top') +
    goldZones.map(([g, c]) => paint(GOLD_SHAPE, 'gold' + g, c)).join('') +
    `<g filter="url(#soft)">` +
    goldZones.map(([g, c]) => paint(GOLD_CORE_SHAPE, 'core' + g, c)).join('') +
    `</g>` +
    `</svg>`
  );
}

export default getBackgroundSvg;
